// A JavaScript cell that returns a string of HTML gets it drawn as a page.
// It's a snapshot: nb is read once, when the cell runs.
const departures = nb.get('departures') ?? [];
const stop = nb.get('stop') ?? 'Bus stop';
const lateAfter = nb.get('late_after') ?? 2;    // set by the slider further down

// Text from data goes through esc(), so '&' and '<' show up as text instead of as HTML.
const esc = (text) => String(text).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

if (departures.length === 0) return '<p>Run the Python cell first.</p>';

const late = departures.filter((d) => d.delay > lateAfter);
const rows = departures.map((d) => `
  <tr>
    <td>${d.scheduled}</td>
    <td><span class="route">${esc(d.route)}</span></td>
    <td class="dest">${esc(d.destination)}</td>
    ${d.delay > lateAfter
      ? `<td class="late">+${d.delay} min late</td>`
      : '<td class="ok">On time</td>'}
  </tr>`).join('');

return `
<style>
  .board { background: #0c0a09; color: #fbbf24; font: 15px/1.5 ui-monospace, Consolas, monospace; border-radius: 10px; padding: 14px 18px; }
  .head { display: flex; justify-content: space-between; gap: 12px; border-bottom: 1px solid #44403c; padding-bottom: 8px; margin-bottom: 4px; }
  .stop { font-weight: 700; letter-spacing: .04em; text-transform: uppercase; }
  .count { color: #a8a29e; }
  table { width: 100%; border-collapse: collapse; }
  td { padding: 3px 8px 3px 0; white-space: nowrap; }
  td.dest { width: 100%; white-space: normal; }
  .route { color: #0c0a09; background: #fbbf24; border-radius: 4px; padding: 0 6px; font-weight: 700; }
  .ok { color: #4ade80; text-align: right; }
  .late { color: #f87171; text-align: right; }
  .foot { color: #78716c; font-size: 12px; margin-top: 8px; }
</style>
<div class="board">
  <div class="head">
    <span class="stop">${esc(stop)}</span>
    <span class="count">${late.length} of ${departures.length} late (more than ${lateAfter} min)</span>
  </div>
  <table>${rows}</table>
  <div class="foot">Drawn by JavaScript at ${new Date().toLocaleTimeString()}, when this cell ran</div>
</div>`;

// A JavaScript cell can return a chart as easily as HTML: return a Vega-Lite spec.
const routeDelays = nb.get('route_delays') ?? [];

return {
  $schema: 'https://vega.github.io/schema/vega-lite/v5.json',
  title: 'Average delay by route (worked out in Python)',
  width: 520,
  height: 160,
  data: { values: routeDelays },
  mark: { type: 'bar', cornerRadiusEnd: 4, color: '#f59e0b' },
  encoding: {
    y: { field: 'route', type: 'nominal', sort: '-x', title: 'Route' },
    x: { field: 'average', type: 'quantitative', title: 'Average delay (min)' },
    tooltip: [
      { field: 'route', title: 'Route' },
      { field: 'average', title: 'Average (min)' },
      { field: 'worst', title: 'Worst (min)' },
      { field: 'buses', title: 'Buses' },
    ],
  },
};
